actions.script:
def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess')
    .parameters([transactionId:transactionId,customerPartyId:customerPartyId]).call()
if (!access?.allowed) return
def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).forUpdate(true).one()
if (txn.statusId != 'PtCreated') { ec.message.addError('Credit terms can only be assigned to an open sale.'); return }
def customer = ec.entity.find('mantle.party.Party').condition('partyId',customerPartyId).one()
def defaultDays = customer.creditDays
def days = creditDays != null ? creditDays : defaultDays
if (days != null && (days < 0 || days > 3650)) { ec.message.addError('Credit days must be a whole number from 0 to 3650.'); return }
boolean override = creditDays != null && defaultDays != null && creditDays != defaultDays
if (override && !(ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN'))) {
    ec.message.addError('A manager must authorize a term different from this customer’s saved credit days.'); return
}
if (override && !termsReason?.trim()) { ec.message.addError('Enter a reason for the credit-term override.'); return }
def zone = ec.user.timeZone.toZoneId()
def issuedDay = ec.user.nowTimestamp.toInstant().atZone(zone).toLocalDate()
txn.creditDays = days
txn.creditDueDate = days != null ? java.sql.Date.valueOf(issuedDay.plusDays(days as long)) : null
txn.creditTimeZone = zone.id
txn.creditTermsReason = override ? termsReason.trim() : 'Customer credit days'
txn.creditTermsByPartyId = ec.user.userAccount?.partyId
txn.update()

bills = []
def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess')
    .parameter('transactionId',transactionId).call()
if (!access?.allowed) return
def shop = ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call()?.activeShopId
def view = sourceModuleId == 'kot' ? 'zenith.erp.pos.KotTransactionDetailView' : 'zenith.erp.pos.RetailPosTransactionView'
def find = ec.entity.find(view).condition('organizationPartyId',access.organizationPartyId).condition('isCredit','Y')
    .distinct(true)
if (shop) find.condition('facilityId',shop)
if (access.terminalRestricted) {
    find.condition('terminalId','in',access.allowedTerminalIds ?: ['__NONE__'])
        .condition('operatorPartyId',ec.user.userAccount?.partyId)
}
if (transactionId) {
    def bill = find.condition('transactionId',transactionId).one()
    if (bill) bills = [bill]
    else ec.message.addError('This credit bill is unavailable in the current workspace.')
} else {
    bills = find.orderBy('-entryDate').list()
}

def scope = ec.service.sync().name('zenith.pos.PosCreditServices.get#ScopedPosCreditBills')
    .parameter('sourceModuleId',sourceModuleId).call()
if (ec.message.hasError()) return
def crTxns = scope.bills ?: []
def crSearch = (search ?: '').toLowerCase()
// ---- all-time stats (across every credit bill, before the search filter) ----
def _nowCr = ec.user.nowTimestamp
def _cCr = java.util.Calendar.getInstance(); _cCr.setTime(_nowCr); _cCr.set(java.util.Calendar.DAY_OF_MONTH, 1); _cCr.set(java.util.Calendar.HOUR_OF_DAY,0); _cCr.set(java.util.Calendar.MINUTE,0); _cCr.set(java.util.Calendar.SECOND,0)
def _crMonthStart = new java.sql.Timestamp(_cCr.getTimeInMillis())
def creditState = { tx, due ->
    if(tx.statusId!='PtCompleted') return 'Cancelled'
    if(due<=0) return 'Settled'
    if(!tx.creditDueDate){def _t=_nowCr.toInstant().atZone(java.time.ZoneId.of(ec.user.timeZone.ID)).toLocalDate(); return (tx.entryDate && java.time.temporal.ChronoUnit.DAYS.between(tx.entryDate.toInstant().atZone(java.time.ZoneId.of(ec.user.timeZone.ID)).toLocalDate(), _t) > 30) ? 'Overdue' : 'Open'}
    def today=_nowCr.toInstant().atZone(java.time.ZoneId.of(tx.creditTimeZone ?: ec.user.timeZone.ID)).toLocalDate()
    def remaining=java.time.temporal.ChronoUnit.DAYS.between(today,tx.creditDueDate.toLocalDate())
    remaining<0?'Overdue':remaining<=2?'Due soon':'Open'
}
def crAllCount = crTxns.size(); def crOutCount = 0; def crOutSum = 0 as BigDecimal; def crOverdue = 0
def creditTxnIds = crTxns.collect { it.transactionId }
def creditPayments = creditTxnIds ? ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId','in',creditTxnIds).orderBy('paymentDate,paymentId').list().groupBy { it.transactionId } : [:]

crTxns.each { tx -> def _o = ((tx.payableAmount ?: 0) as BigDecimal) - ((tx.paidAmount ?: 0) as BigDecimal); if (_o > 0) { crOutCount++; crOutSum += _o; if (creditState(tx,_o)=='Overdue') crOverdue++ } }
def crPaidMonthAmt = 0 as BigDecimal; def crPaidMonthCount = 0
if (creditTxnIds) {
    def _pm = ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId","in",creditTxnIds).condition("paymentDate","greater-equals",_crMonthStart).list()
    crPaidMonthAmt = _pm.sum { (it.amount ?: 0) as BigDecimal } ?: (0 as BigDecimal)
    crPaidMonthCount = _pm.collect { it.transactionId }.unique().size()
}
// ---- list (search-filtered) ----
def crBills = []
crTxns.each { tx ->
    if (crSearch && !((tx.transactionNumber ?: '').toLowerCase().contains(crSearch) || (tx.customerName ?: '').toLowerCase().contains(crSearch) || (tx.customerPhone ?: '').toLowerCase().contains(crSearch))) return
    def items = ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", tx.transactionId).list()
    def payable = (tx.payableAmount ?: 0) as BigDecimal
    def paid = (tx.paidAmount ?: 0) as BigDecimal
    def payments = creditPayments[tx.transactionId] ?: []
    def lastPayment = payments ? payments[-1].paymentDate : null
    def state = creditState(tx,payable-paid)
    crBills.add([dueDate:tx.creditDueDate?.toString(),creditStatus:state,
        lastPayment:lastPayment ? ec.l10n.format(lastPayment,'dd MMM yyyy, hh:mm a z') : null,
        settledOn:state=='Settled' && lastPayment ? ec.l10n.format(lastPayment,'dd MMM yyyy, hh:mm a z') : null,txId: tx.transactionId, billNo: tx.transactionNumber ?: tx.transactionId,
        date: ec.l10n.format(tx.entryDate, 'dd/MM/yyyy hh:mm a'), ts: (tx.entryDate ? tx.entryDate.getTime() : 0L),
        customer: tx.customerName ?: 'Walk-In', phone: tx.customerPhone ?: '',
        grand: payable, paid: paid, outstanding: payable - paid, itemCount: items.size()])
}
def crTotalOutstanding = 0 as BigDecimal
crBills.each { crTotalOutstanding += (it.outstanding as BigDecimal) }
creditList = [success:true, action:'creditBills', bills:crBills, total:crBills.size(), totalOutstanding:crTotalOutstanding,
    allCount:crAllCount, outCount:crOutCount, outSum:crOutSum, overdueCount:crOverdue, paidMonthAmt:crPaidMonthAmt, paidMonthCount:crPaidMonthCount]

if (sourceModuleId == 'kot' && paymentMethod == 'Cash') {
    def bill = billScope.bills[0]
    if (!collectionSessionId && bill.facilityId) {
        def drawers = ec.entity.find('zenith.erp.pos.PosSessionView')
            .condition('organizationPartyId',bill.organizationPartyId).condition('facilityId',bill.facilityId)
            .condition('operatorPartyId',ec.user.userAccount?.partyId).condition('statusId','PsOpen').list()
        collectionSessionId = drawers.find { it.sessionId == bill.sessionId }?.sessionId
        if (!collectionSessionId && drawers.size() == 1) collectionSessionId = drawers[0].sessionId
    }
    def drawer = collectionSessionId ? ec.service.sync().name('zenith.pos.KotServices.get#BillingSession')
        .parameter('sessionId',collectionSessionId).call() : null
    if (drawer?.terminal?.facilityId != bill.facilityId || !drawer?.session) {
        ec.message.addError('Open your KOT counter in this shop before collecting cash for this credit bill.')
    }
}

def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('customerPartyId',customerPartyId).call()
if (!access?.allowed) return
if (!(ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN'))) { ec.message.addError('Only a manager can change customer credit terms.'); return }
if (creditDays < 0 || creditDays > 3650 || !reason?.trim()) { ec.message.addError('Enter 0–3650 credit days and a reason.'); return }
def customer = ec.entity.find('mantle.party.Party').condition('partyId',customerPartyId).forUpdate(true).one()
def oldDays = customer.creditDays
customer.creditDays = creditDays; customer.update()
if (oldDays != creditDays) ec.service.sync().name('create#zenith.erp.pos.PosCreditTermsChange').parameters([
    organizationPartyId:access.organizationPartyId,customerPartyId:customerPartyId,oldDays:oldDays,newDays:creditDays,
    changedDate:ec.user.nowTimestamp,changedByPartyId:ec.user.userAccount?.partyId,reason:reason.trim()]).call()

if (!(ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN'))) { ec.message.addError('Only a manager can change a bill due date.'); return }
def allowedBill = ec.service.sync().name('zenith.pos.PosCreditServices.get#ScopedPosCreditBills')
    .parameters([sourceModuleId:sourceModuleId,transactionId:transactionId]).call()?.bills?.find()
if (!allowedBill) return
def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).forUpdate(true).one()
if (txn.isCredit != 'Y' || txn.statusId != 'PtCompleted' || !reason?.trim()) { ec.message.addError('Select an active credit bill and enter a reason.'); return }
if (dueDate == txn.creditDueDate) return
ec.service.sync().name('create#zenith.erp.pos.PosCreditTermsChange').parameters([
    organizationPartyId:allowedBill.organizationPartyId,customerPartyId:txn.customerPartyId,transactionId:transactionId,
    oldDueDate:txn.creditDueDate,newDueDate:dueDate,changedDate:ec.user.nowTimestamp,
    changedByPartyId:ec.user.userAccount?.partyId,reason:reason.trim()]).call()
txn.creditDueDate = dueDate; txn.update()

def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('customerPartyId',customerPartyId).call()
if (!access?.allowed) return
if (!(ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN'))) { ec.message.addError('Only a manager can configure customer reminders.'); return }
if (!['Y','N'].contains(consent) || !['SMS','WhatsApp','Email'].contains(channel) || intervalDays < 1 || intervalDays > 365 || maxAttempts < 1 || maxAttempts > 12) {
    ec.message.addError('Choose a channel, consent, 1–365 days between reminders, and a maximum of 1–12 attempts.'); return
}
ec.service.sync().name('store#zenith.erp.pos.PosCreditReminderPolicy').parameters([
    organizationPartyId:access.organizationPartyId,customerPartyId:customerPartyId,consent:consent,channel:channel,
    intervalDays:intervalDays,maxAttempts:maxAttempts,changedDate:ec.user.nowTimestamp,changedByPartyId:ec.user.userAccount?.partyId]).call()
if (consent == 'N') ec.entity.find('zenith.erp.pos.PosCreditReminder').condition('organizationPartyId',access.organizationPartyId)
    .condition('customerPartyId',customerPartyId).condition('deliveryStatus','Awaiting provider').list().each {
        it.deliveryStatus='Cancelled'; it.failureReason='Customer opted out before delivery.'; it.update()
    }

ec.user.loginAnonymousIfNoUser()
def now = ec.user.nowTimestamp
ec.entity.find('zenith.erp.pos.PosCreditReminderPolicy').condition('consent','Y').list().each { policy ->
    def bills = ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',policy.organizationPartyId)
        .condition('customerPartyId',policy.customerPartyId).condition('isCredit','Y').list()
    bills.each { bill ->
        def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',bill.transactionId).forUpdate(true).one()
        def pending = ec.entity.find('zenith.erp.pos.PosCreditReminder').condition('organizationPartyId',policy.organizationPartyId)
            .condition('transactionId',txn.transactionId).condition('deliveryStatus','Awaiting provider').list()
        def paid = ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',txn.transactionId).list().sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
        def remaining = ((txn.payableAmount ?: 0) as BigDecimal) - paid
        if (txn.statusId != 'PtCompleted' || remaining <= 0) {
            pending.each { it.deliveryStatus = 'Cancelled'; it.failureReason = 'Bill settled or cancelled before delivery.'; it.update() }; return
        }
        pending.each { it.outstandingAmount = remaining; it.update() }
        if (!txn.creditDueDate) return
        def today = now.toInstant().atZone(java.time.ZoneId.of(txn.creditTimeZone ?: 'UTC')).toLocalDate()
        if (!today.isAfter(txn.creditDueDate.toLocalDate())) return
        def attempts = ec.entity.find('zenith.erp.pos.PosCreditReminder').condition('transactionId',txn.transactionId)
            .condition('organizationPartyId',policy.organizationPartyId).orderBy('-createdDate').list()
        if (attempts.size() >= policy.maxAttempts || attempts.any { it.deliveryStatus == 'Awaiting provider' }) return
        if (attempts && now.time - attempts[0].createdDate.time < (policy.intervalDays as long) * 86400000L) return
        ec.service.sync().name('create#zenith.erp.pos.PosCreditReminder').parameters([
            organizationPartyId:policy.organizationPartyId,transactionId:txn.transactionId,customerPartyId:txn.customerPartyId,
            eventKey:txn.transactionId + ':' + attempts.size(),createdDate:now,channel:policy.channel,outstandingAmount:remaining,
            deliveryStatus:'Awaiting provider',failureReason:'No supported delivery provider is configured. No customer message was sent.']).call()
    }
}
